const items = $input.all();
const output = [];

for (const item of items) {
  const data = item.json;
  output.push({
    json: {
      job_id: data.id || data.source_job_id,
      title: data.title || "Unspecified",
      company: data.company_name || "Unspecified",
      location: data.location_name || "Casablanca",
      sector: data.sector || "IT / Digital",
      contract: data.contract_type || "CDI",
      description_snippet: (data.description || "").substring(0, 800)
    }
  });
}

return output;

const output = [];

for (const item of $input.all()) {
  try {
    let text = item.json.output || item.json.text || "{}";
    // Clean markdown if LLM adds ```json
    text = text.replace(/```json/g, "").replace(/```/g, "").trim();
    const parsed = JSON.parse(text);

    const original = $('Prepare LLM Context Payload').item.json;

    output.push({
      json: {
        job_id: original.job_id,
        title: original.title,
        estimated_salary: parsed.estimated_salary_mad || 12000,
        formatted_salary: `${parsed.estimated_salary_mad || 12000} MAD (AI Est.)`,
        seniority_level: parsed.seniority_level || "Mid",
        workplace_type: parsed.workplace_type || "On-site",
        skills: parsed.top_skills || []
      }
    });
  } catch (e) {
    const original = $('Prepare LLM Context Payload').item.json;
    output.push({
      json: {
        job_id: original.job_id,
        title: original.title,
        estimated_salary: 11000,
        formatted_salary: "11000 MAD (AI Est.)",
        seniority_level: "Mid",
        workplace_type: "On-site",
        skills: []
      }
    });
  }
}

return output;
